ValidationRule.errorConditionFormula:
AND(
    RecordType.DeveloperName == "RFQ",
    ISCHANGED(Status),
    NOT(
        AND(
            $Profile.Name = "Carlton CPT User",
            ISPICKVAL(PRIORVALUE(Status), "Submitted"),
            ISPICKVAL(Status, "Assigned")
        )
    ),

    OR(
        /* 1. Invalid status transitions for everyone */
        NOT(
            OR(
                AND(
                    ISPICKVAL(PRIORVALUE(Status), "Assigned"),
                    ISPICKVAL(Status, "In Progress")
                ),
                AND(
                    ISPICKVAL(PRIORVALUE(Status), "In Progress"),
                    ISPICKVAL(Status, "Awaiting Information")
                ),
                AND(
                    ISPICKVAL(PRIORVALUE(Status), "Awaiting Information"),
                    ISPICKVAL(Status, "In Progress")
                ),
                AND(
                    ISPICKVAL(PRIORVALUE(Status), "In Progress"),
                    OR(
                        ISPICKVAL(Status, "Completed"),
                        ISPICKVAL(Status, "Rejected"),
                        ISPICKVAL(Status, "Cancelled")
                    )
                )
            )
        ),

        /* 2. Block non-CPT users from making any status transitions */
        $Profile.Name <> "Carlton CPT User"
    ),
    $Profile.Name <> "System Administrator",
    NOT($CustomMetadata.Trigger_Framework_Config_CC__mdt.Case.Bypass_Validation_CC__c)

)
